    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda x: sum(row.count(x) for row in grid))
    # Each diagonal adjacency defines a ray in both directions. Extend until
    # reaching the grid edge or another already-painted/input cell.
    edges = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    edges.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in edges:
        for sign in (-1, 1):
            rr, cc = r, c
            while True:
                nr, nc = rr + sign * dr, cc + sign * dc
                if not (0 <= nr < h and 0 <= nc < w):
                    break
                if grid[nr][nc] != bg:
                    break
                out[nr][nc] = color
                rr, cc = nr, nc
    return out

